typedef float time_value_t;

class kellyslater_controller {
    char padding[0x38];
public:
    int get_super_state() const { return *(const int *)((const char *)this + 0x38); }
};

class world_dynamics_system {
    char padding[0xf8];
    kellyslater_controller **controllers;
public:
    kellyslater_controller *get_ks_controller(int player) { return controllers[player]; }
};

class game {
    char padding[0xbc];
    int active_player;
public:
    int get_active_player() const { return active_player; }
};

class camera {
public:
    virtual void frame_advance(float);
};

class game_view {
    char padding[0x28];
    camera *current_view_camera;
public:
    camera *get_current_view_camera() { return current_view_camera; }
};

class app {
    char padding[0x10];
    game_view *the_game;
public:
    static app *inst();
    game_view *get_game() { return the_game; }
};

extern app *global_app;
inline app *app::inst() { return global_app; }

extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;

enum { SUPER_STATE_FLYBY = 1 };

class KSReplay {
    char padding0[0x10];
    int status;
    char padding1[0x4c];
    void *frame;
public:
    enum KSReplayStatus {
        REPLAY_IGNORE,
        REPLAY_RECORD,
        REPLAY_PLAYBACK,
        REPLAY_PAUSED
    };

    void SaveFrame();
    void RestoreNextFrame(time_value_t time_inc);
    bool Done();
    void Tick(bool running, time_value_t time_inc);
};

void KSReplay::Tick(bool running, time_value_t time_inc)
{
  if(frame == NULL)		// True when not recording a replay, such as in multiplayer mode
    return;


  switch(status)
	{
		case REPLAY_IGNORE:
      break;

		case REPLAY_RECORD  :
      if(SUPER_STATE_FLYBY != g_world_ptr->get_ks_controller(g_game_ptr->get_active_player())->get_super_state())  // Don't record during flyby
      {
			  if (running && time_inc>0)
				  SaveFrame();
      }
			break;

		case REPLAY_PLAYBACK:
      RestoreNextFrame(time_inc);
      if(Done())
        status = REPLAY_PAUSED;
			break;

		case REPLAY_PAUSED  :

      // Update camera
      app::inst()->get_game()->get_current_view_camera()->frame_advance (0.0f);
			break;
	}
}
